import{_ as d,l as c,o as e,c as i,v as o,p as n,x as t,d as s,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"管程与条件变量","description":"","frontmatter":{"title":"管程与条件变量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/monitor-condvar.md","filePath":"cs/monitor-condvar.md","lastUpdated":1789023840000}'),E={name:"cs/monitor-condvar.md"};function h(m,a,A,_,B,u){const r=c("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="管程与条件变量" tabindex="-1">管程与条件变量 <a class="header-anchor" href="#管程与条件变量" aria-label="Permalink to &quot;管程与条件变量&quot;">​</a></h1><div class="epigraph"><p>管程把共享数据与操作它的过程包在一起；过程在管程内互斥执行，条件变量用于等待不变量重新成立。</p><footer>—— 据 Hoare, Monitors: An Operating System Structuring Concept, CACM 1974 整理</footer></div><p><a href="/cs/semaphore">上一课</a>能计数等待，但 P/V 散落在各处，编译器看不见「哪把锁护哪块数据」。缺口是语言级模块：进入即持锁，退出即放锁，等待改写成条件变量。本课钉管程与 <code>wait</code>/<code>signal</code>，不把死锁图谱画完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用三个信号量实现有界缓冲，容易 V 错对象。管程约定：模块内任意时刻至多一个活动过程（互斥自动）。当不变量暂时不成立（缓冲空），过程在条件变量上等待——等待必须<strong>释放管程锁</strong>，否则无人能生产。缺口是这套括号，不是新的硬件原子。</p><p>Hoare 语义：<code>signal</code> 立即切到等待者，信号方暂停。Mesa/Java 语义：<code>signal</code> 只唤醒，被唤醒者回头再检查条件。主干标明差别，实现课默认 Mesa：等待必须写成循环。</p><p><span class="marginnote">条件变量本身不记布尔值。布尔在管程的普通变量里；条件变量只是等待队列的名字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>进入管程 = 获得隐含互斥。<code>wait(c)</code>：释放互斥，挂到 \\(c\\)，被唤醒后重新获得互斥。<code>signal(c)</code> / <code>broadcast(c)</code>：唤醒一个或全部。有界缓冲的 <code>put</code>/<code>get</code> 都在管程内，空与满各用一个条件变量。</p>',9)),(e(),n(p,null,{default:t(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENTER%5B%22%E8%BF%9B%E5%85%A5%3A%20%E6%8C%81%E7%AE%A1%E7%A8%8B%E9%94%81%22%5D%20--%3E%20CHECK%5B%22%E6%A3%80%E6%9F%A5%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20CHECK%20--%3E%20WAIT%5B%22wait%3A%20%E6%94%BE%E9%94%81%E5%B9%B6%E7%9D%A1%22%5D%0A%20%20WAIT%20--%3E%20RE%5B%22%E5%94%A4%E9%86%92%E5%90%8E%E9%87%8D%E6%96%B0%E6%8C%81%E9%94%81%22%5D%0A%20%20CHECK%20--%3E%20BODY%5B%22%E4%BF%AE%E6%94%B9%E5%85%B1%E4%BA%AB%E6%95%B0%E6%8D%AE%22%5D%0A%20%20BODY%20--%3E%20SIG%5B%22signal%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>管程把<a href="/cs/race-critical">临界区</a>变成类型边界：模块外碰不到裸计数。条件等待把「互斥」与「等某谓词」拆开，避免用信号量兼做两职时的协议错误。内核里的等待队列加睡眠锁，是管程的手写版；POSIX <code>pthread_cond</code> 是用户版。</p><p>与信号量相比，谁该被唤醒由条件变量指名，而不是「任意 V」。广播可能惊群，这是性能边界，不是语义必须。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Java <code>synchronized</code> 与 <code>Lock</code> 的全部 API 对照完，不引入无锁 condvar。Hoare 立即切换在当代运行时少见，读论文时不要默认 Linux 是 Hoare。死锁仍可能：两个管程各等对方，四个条件下一课才列。</p><p>嵌套管程调用会重入锁或死锁，语言实现必须规定；教学默认过程不跨越两个管程持锁。</p><p>后课默认：共享对象可用管程括号；<code>wait</code> 写在循环里（Mesa）。同步原语互等导致永久阻塞，下一课用 Coffman 条件刻画。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>管程 = 数据 + 互斥过程；条件变量只是等待队列。</li><li>Mesa：唤醒后重新检查谓词。</li><li>跨对象互等仍可死锁。</li><li>出处：Hoare, <em>CACM</em> 1974；Lampson and Redell, Mesa, 1980（Mesa 语义）。</li></ul>',9))])}const T=d(E,[["render",h]]);export{C as __pageData,T as default};
